const cfg = $('Config IA').first().json || {};
const ent = $('Receber pedido').first().json || {};
const tarefa = ['conversa','documento','simples','decisao'].includes(ent.tarefa) ? ent.tarefa : 'conversa';
const mapa = { conversa: cfg.ia_conversa, documento: cfg.ia_documento, simples: cfg.ia_simples, decisao: 'jev' };
let provedor = String(ent.provedor || mapa[tarefa] || 'openai').toLowerCase();
if (tarefa === 'decisao' && cfg.ia_decisao_modo === 'desligado' && !ent.provedor) provedor = 'desligado';
if (!['openai','claude','jev','desligado'].includes(provedor)) provedor = 'openai';
const sistema = String(ent.sistema || '');
const mensagens = Array.isArray(ent.mensagens) ? ent.mensagens : [{ role: 'user', content: String(ent.texto || '') }];
const esquema = ent.esquema && ent.esquema.schema ? ent.esquema : null;
const maxTokens = Number(ent.max_tokens) || 4000;

// OpenAI (formato atual do Dyno)
const msgsOpenai = (sistema ? [{ role: 'system', content: sistema }] : []).concat(mensagens);
const openai = { model: ent.modelo_openai || cfg.ia_modelo_openai || 'gpt-5.6-luna', messages: msgsOpenai };
if (esquema) openai.response_format = { type: 'json_schema', json_schema: { name: esquema.name || 'resposta', strict: true, schema: esquema.schema } };

// Claude: converte partes do formato OpenAI
const dataUrl = s => { const m = /^data:([^;]+);base64,(.*)$/s.exec(String(s || '')); return m ? { media_type: m[1], data: m[2] } : null; };
const parte = p => {
  if (typeof p === 'string') return { type: 'text', text: p };
  if (p.type === 'text') return { type: 'text', text: p.text };
  if (p.type === 'image_url') { const d = dataUrl(p.image_url && p.image_url.url); return d ? { type: 'image', source: { type: 'base64', media_type: d.media_type, data: d.data } } : { type: 'image', source: { type: 'url', url: p.image_url.url } }; }
  if (p.type === 'file') { const d = dataUrl(p.file && p.file.file_data); return d ? { type: 'document', source: { type: 'base64', media_type: d.media_type, data: d.data } } : { type: 'text', text: '[arquivo]' }; }
  return { type: 'text', text: JSON.stringify(p) };
};
const msgsClaude = mensagens.filter(m => m.role !== 'system').map(m => ({ role: m.role === 'assistant' ? 'assistant' : 'user', content: Array.isArray(m.content) ? m.content.map(parte) : String(m.content || '') }));
const modeloClaude = tarefa === 'simples' ? (cfg.ia_modelo_claude_simples || 'claude-haiku-4-5') : (cfg.ia_modelo_claude || 'claude-sonnet-5-5');
const claude = { model: ent.modelo_claude || modeloClaude, max_tokens: maxTokens, messages: msgsClaude };
let sisClaude = sistema;
if (esquema) {
  const nome = esquema.name || 'resposta';
  claude.tools = [{ name: nome, description: 'Devolva a resposta completa neste formato.', input_schema: esquema.schema }];
  // Os modelos novos do Claude nao aceitam tool_choice forcado ('tool'/'any'): usamos 'auto' e pedimos a ferramenta no sistema.
  claude.tool_choice = { type: 'auto' };
  sisClaude = (sistema ? sistema + '\n\n' : '') + 'Responda SEMPRE chamando a ferramenta "' + nome + '" com o resultado completo. Nao escreva texto fora dela.';
}
if (sisClaude) claude.system = [{ type: 'text', text: sisClaude, cache_control: { type: 'ephemeral' } }];

// Jev: decisao tipada
const jev = { model: cfg.ia_modelo_jev || 'jev-latest', state: (ent.decisao && ent.decisao.state) || '', questions: (ent.decisao && ent.decisao.questions) || {} };

return [{ json: { tarefa, provedor, esquema: !!esquema, openai, claude, jev, inicio: Date.now() } }];

const ped = $('Montar pedido').first().json;
const r = $input.first().json || {};
const ms = Date.now() - ped.inicio;
const tenta = s => { try { return JSON.parse(s); } catch (e) { return null; } };
if (ped.provedor === 'desligado') return [{ json: { ok: false, provedor: 'desligado', motivo: 'camada de decisao desligada', ms } }];
// OpenAI
if (Array.isArray(r.choices)) {
  const texto = String((r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '');
  const reserva = ped.provedor !== 'openai';
  return [{ json: { ok: true, provedor: 'openai', reserva, modelo: r.model, texto, json: ped.esquema ? tenta(texto) : null, uso: r.usage || null, ms } }];
}
// Claude
if (r.type === 'message' && Array.isArray(r.content)) {
  const tool = r.content.find(c => c.type === 'tool_use');
  const texto = r.content.filter(c => c.type === 'text').map(c => c.text).join('\n');
  return [{ json: { ok: true, provedor: 'claude', reserva: false, modelo: r.model, texto: tool ? JSON.stringify(tool.input) : texto, json: tool ? tool.input : (ped.esquema ? tenta(texto) : null), uso: r.usage || null, ms } }];
}
// Jev ou erro
if (ped.provedor === 'jev' && !r.error && r.answers) {
  const resp = {};
  for (const [k, a] of Object.entries(r.answers)) resp[k] = a.type === 'choice' ? { valor: a.choice, confianca: a.confidence } : a.type === 'score' ? { valor: a.score, confianca: a.confidence } : { valor: a.noul >= 0.5, probabilidade: a.noul };
  return [{ json: { ok: true, provedor: 'jev', modelo: r.model || ped.jev.model, json: resp, decisao: r, uso: r.usage || null, ms } }];
}
const erro = r.error ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error))) : 'resposta inesperada';
return [{ json: { ok: false, provedor: ped.provedor, erro: String(erro).slice(0, 300), ms } }];
